// frontend-project/src/components/Reports.js
import React, { useState } from 'react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { FaChartBar, FaDownload } from 'react-icons/fa';

const Reports = () => {
  const [reportType, setReportType] = useState('monthly');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [reportData, setReportData] = useState(null);
  const [departmentSummary, setDepartmentSummary] = useState(null);
  const [loading, setLoading] = useState(false);

  const months = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  const fetchMonthlyReport = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`/reports/monthly-salary?year=${selectedYear}&month=${selectedMonth}`);
      setReportData(response.data);
      setDepartmentSummary(null);
    } catch (error) {
      toast.error('Failed to fetch monthly report');
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartmentSummary = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/reports/department-summary');
      setDepartmentSummary(response.data);
      setReportData(null);
    } catch (error) {
      toast.error('Failed to fetch department summary');
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateReport = () => {
    if (reportType === 'monthly') {
      fetchMonthlyReport();
    } else {
      fetchDepartmentSummary();
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Reports & Analytics</h2>
          <p className="text-gray-600 mt-1">View salary reports and department analytics</p>
        </div>
      </div>

      <div className="card mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Report Type</label>
            <select
              value={reportType}
              onChange={(e) => setReportType(e.target.value)}
              className="input-field"
            >
              <option value="monthly">Monthly Salary Report</option>
              <option value="department">Department Summary</option>
            </select>
          </div>

          {reportType === 'monthly' && (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Year</label>
                <input
                  type="number"
                  value={selectedYear}
                  onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                  className="input-field"
                  min="2020"
                  max="2030"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Month</label>
                <select
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                  className="input-field"
                >
                  {months.map((month, index) => (
                    <option key={index} value={index + 1}>{month}</option>
                  ))}
                </select>
              </div>
            </>
          )}

          <div className="flex items-end">
            <button
              onClick={handleGenerateReport}
              className="btn-primary w-full flex items-center justify-center gap-2"
            >
              <FaChartBar /> Generate Report
            </button>
          </div>
        </div>
      </div>

      {loading && (
        <div className="text-center py-8">
          <div className="text-lg">Loading report...</div>
        </div>
      )}

      {reportData && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-4">
            Salary Report - {months[selectedMonth - 1]} {selectedYear}
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div className="bg-blue-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Employees</p>
              <p className="text-2xl font-bold text-blue-600">{reportData.summary.totalEmployees}</p>
            </div>
            <div className="bg-green-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Gross Salary</p>
              <p className="text-2xl font-bold text-green-600">${reportData.summary.totalGrossSalary.toLocaleString()}</p>
            </div>
            <div className="bg-purple-50 p-4 rounded-lg">
              <p className="text-sm text-gray-600">Total Net Salary</p>
              <p className="text-2xl font-bold text-purple-600">${reportData.summary.totalNetSalary.toLocaleString()}</p>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Employee</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Gross Salary</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Deductions</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Net Salary</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {reportData.payments.map((payment, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {payment.employee?.firstName} {payment.employee?.lastName}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">${payment.grossSalary.toLocaleString()}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">${payment.deductions.toLocaleString()}</td>
                    <td className="px-6 py-4 text-sm text-green-600 font-semibold">${payment.netSalary.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {departmentSummary && !loading && (
        <div className="card">
          <h3 className="text-xl font-bold mb-4">Department Salary Summary</h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            {departmentSummary.map((dept, index) => (
              <div key={index} className="bg-gradient-to-r from-blue-50 to-indigo-50 p-4 rounded-lg">
                <h4 className="font-semibold text-lg text-gray-800 mb-2">{dept.department}</h4>
                <div className="space-y-1">
                  <p className="text-sm text-gray-600">Employees: <span className="font-semibold">{dept.employeeCount}</span></p>
                  <p className="text-sm text-gray-600">Total Payroll: <span className="font-semibold text-green-600">${dept.totalPayroll.toLocaleString()}</span></p>
                  <p className="text-sm text-gray-600">Average Salary: <span className="font-semibold text-blue-600">${dept.averageSalary.toLocaleString()}</span></p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reports;
